{
  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    mem = {}
    for i, trial in enumerate(trials):
        sig = trial['signature']
        mem[sig] = {
            'last_trial': i,
            'reflection': trial['reflection'],
            'signature': sig,
            'success': trial['success']
        }
    if len(mem) > capacity:
        sorted_entries = sorted(mem.values(), key=lambda x: (x['success'], -x['last_trial'], x['signature']))
        kept = sorted_entries[:capacity]
    else:
        kept = list(mem.values())
    kept.sort(key=lambda x: x['last_trial'])
    memory = kept
    signatures = [e['signature'] for e in memory]
    return {'memory': memory, 'signatures': signatures}"
}
